"use client"

import { CalendarIcon } from "lucide-react"
import * as React from "react"
import type { DateRange } from "react-day-picker"

import { Button } from "@/components/ui/button"
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover"
import { cn } from "@/lib/utils"

import { DvGregorianCalendar, formatGregorianDate } from "./dv-gregorian-calendar"
import { DvHijriCalendar, formatHijriDate } from "./dv-hijri-calendar"

type DvDatePickerCalendarProps = Omit<
  React.ComponentProps<typeof DvHijriCalendar>,
  "dir" | "lang" | "mode" | "onSelect" | "selected"
>

type DvDatePickerCommonProps = {
  calendar?: "gregorian" | "hijri"
  placeholder?: string
  disabled?: boolean
  required?: boolean
  dir?: "ltr" | "rtl"
  lang?: string
  open?: boolean
  defaultOpen?: boolean
  onOpenChange?: (open: boolean) => void
  "aria-label"?: string
  className?: string
  triggerClassName?: string
  contentClassName?: string
  calendarProps?: DvDatePickerCalendarProps
}

type DvDatePickerSingleProps = DvDatePickerCommonProps & {
  mode?: "single"
  value?: Date
  defaultValue?: Date
  onValueChange?: (date: Date | undefined) => void
}

type DvDatePickerRangeProps = DvDatePickerCommonProps & {
  mode: "range"
  value?: DateRange
  defaultValue?: DateRange
  onValueChange?: (range: DateRange | undefined) => void
}

type DvDatePickerProps = DvDatePickerSingleProps | DvDatePickerRangeProps

function DvDatePicker(props: DvDatePickerProps) {
  const {
    calendar = "gregorian",
    placeholder = props.mode === "range" ? "ތާރީޚުގެ ރޭންޖެއް ހޮވާ" : "ތާރީޚެއް ހޮވާ",
    disabled = false,
    required = false,
    dir = "rtl",
    lang = "dv",
    open,
    defaultOpen = false,
    onOpenChange,
    "aria-label": ariaLabel,
    className,
    triggerClassName,
    contentClassName,
    calendarProps,
  } = props
  const [internalOpen, setInternalOpen] = React.useState(defaultOpen)
  const [internalDate, setInternalDate] = React.useState<Date | undefined>(
    props.mode === "range" ? undefined : props.defaultValue
  )
  const [internalRange, setInternalRange] = React.useState<DateRange | undefined>(
    props.mode === "range" ? props.defaultValue : undefined
  )
  const isOpen = open ?? internalOpen
  const selectedDate = props.mode === "range" ? undefined : (props.value ?? internalDate)
  const selectedRange = props.mode === "range" ? (props.value ?? internalRange) : undefined

  function updateOpen(nextOpen: boolean) {
    if (open === undefined) setInternalOpen(nextOpen)
    onOpenChange?.(nextOpen)
  }

  function updateDate(date: Date | undefined) {
    if (props.mode === "range") return
    if (props.value === undefined) setInternalDate(date)
    props.onValueChange?.(date)
    if (date) updateOpen(false)
  }

  function updateRange(range: DateRange | undefined) {
    if (props.mode !== "range") return
    if (props.value === undefined) setInternalRange(range)
    props.onValueChange?.(range)
    if (range?.from && range.to) updateOpen(false)
  }

  const label = selectedDate
    ? formatDate(selectedDate, calendar)
    : selectedRange?.from
      ? selectedRange.to
        ? `${formatDate(selectedRange.from, calendar)} – ${formatDate(selectedRange.to, calendar)}`
        : formatDate(selectedRange.from, calendar)
      : undefined

  return (
    <div data-slot="dv-date-picker" className={cn("w-full", className)}>
      <Popover open={isOpen} onOpenChange={updateOpen}>
        <PopoverTrigger asChild>
          <Button
            type="button"
            variant="outline"
            data-empty={!label}
            disabled={disabled}
            aria-label={ariaLabel ?? placeholder}
            aria-required={required || undefined}
            aria-expanded={isOpen}
            dir={dir}
            lang={lang}
            title={label}
            className={cn(
              "w-full min-w-0 justify-start overflow-hidden text-start font-normal data-[empty=true]:text-muted-foreground",
              triggerClassName
            )}
          >
            <CalendarIcon aria-hidden="true" className="shrink-0" />
            {label ? (
              <bdi dir="rtl" lang="dv" className="min-w-0 flex-1 truncate">
                {label}
              </bdi>
            ) : (
              <span className="min-w-0 flex-1 truncate">{placeholder}</span>
            )}
          </Button>
        </PopoverTrigger>
        <PopoverContent
          align="start"
          dir={dir}
          lang={lang}
          className={cn("w-auto p-0", contentClassName)}
        >
          {calendar === "hijri" && props.mode === "range" ? (
            <DvHijriCalendar
              {...calendarProps}
              mode="range"
              selected={selectedRange}
              onSelect={updateRange}
              dir={dir}
              lang={lang}
            />
          ) : calendar === "hijri" ? (
            <DvHijriCalendar
              {...calendarProps}
              mode="single"
              selected={selectedDate}
              onSelect={updateDate}
              dir={dir}
              lang={lang}
            />
          ) : props.mode === "range" ? (
            <DvGregorianCalendar
              {...calendarProps}
              mode="range"
              selected={selectedRange}
              onSelect={updateRange}
              dir={dir}
            />
          ) : (
            <DvGregorianCalendar
              {...calendarProps}
              mode="single"
              selected={selectedDate}
              onSelect={updateDate}
              dir={dir}
            />
          )}
        </PopoverContent>
      </Popover>
    </div>
  )
}

function formatDate(date: Date, calendar: "gregorian" | "hijri") {
  return calendar === "hijri" ? formatHijriDate(date) : formatGregorianDate(date)
}

export {
  DvDatePicker,
  type DvDatePickerCalendarProps,
  type DvDatePickerProps,
  type DvDatePickerRangeProps,
  type DvDatePickerSingleProps,
  formatGregorianDate,
}

"use client"

import type * as React from "react"

import { Calendar } from "@/components/ui/calendar"

const gregorianMonths = [
  "ޖެނުއަރީ",
  "ފެބްރުއަރީ",
  "މާރިޗު",
  "އޭޕްރީލު",
  "މެއި",
  "ޖޫން",
  "ޖުލައި",
  "އޯގަސްޓް",
  "ސެޕްޓެމްބަރު",
  "އޮކްޓޯބަރު",
  "ނޮވެމްބަރު",
  "ޑިސެމްބަރު",
] as const

const dhivehiWeekdays = ["އާދީއްތަ", "ހޯމަ", "އަންގާރަ", "ބުދަ", "ބުރާސްފަތި", "ހުކުރު", "ހޮނިހިރު"] as const

const dhivehiWeekdayShort = ["އާ", "ހޯ", "އަން", "ބު", "ބުރާ", "ހު", "ހޮ"] as const

function formatGregorianDate(date: Date) {
  return `${date.getDate()} ${gregorianMonths[date.getMonth()]} ${date.getFullYear()}`
}

function formatGregorianMonthYear(date: Date) {
  return `${gregorianMonths[date.getMonth()]} ${date.getFullYear()}`
}

function DvGregorianCalendar({
  formatters,
  labels,
  dir = "rtl",
  lang = "dv",
  ...props
}: React.ComponentProps<typeof Calendar>) {
  return (
    <Calendar
      {...props}
      dir={dir}
      lang={lang}
      formatters={{
        formatCaption: formatGregorianMonthYear,
        formatMonthDropdown: (date) => gregorianMonths[date.getMonth()],
        formatYearDropdown: (date) => String(date.getFullYear()),
        formatWeekdayName: (date) => dhivehiWeekdayShort[date.getDay()],
        ...formatters,
      }}
      labels={{
        labelNav: () => "ކަލަންޑަރުގެ މަސްތައް",
        labelGrid: (date) => formatGregorianMonthYear(date),
        labelMonthDropdown: () => "މަސް ހޮވާ",
        labelYearDropdown: () => "އަހަރު ހޮވާ",
        labelNext: () => "ދެން އޮތް މަސް",
        labelPrevious: () => "ކުރީގެ މަސް",
        labelDayButton: (date) => `${dhivehiWeekdays[date.getDay()]}، ${formatGregorianDate(date)}`,
        labelWeekday: (date) => dhivehiWeekdays[date.getDay()],
        ...labels,
      }}
    />
  )
}

export { DvGregorianCalendar, formatGregorianDate, formatGregorianMonthYear, gregorianMonths }

"use client"

import { DayPicker, enUS, getDateLib } from "@daypicker/hijri"
import { ChevronDownIcon, ChevronLeftIcon, ChevronRightIcon } from "lucide-react"
import * as React from "react"
import { type DayButton, getDefaultClassNames } from "react-day-picker"

import { Button, buttonVariants } from "@/components/ui/button"
import { cn } from "@/lib/utils"

const hijriDateLib = getDateLib({ locale: enUS })

const hijriMonths = [
  "މުޙައްރަމް",
  "ޞަފަރު",
  "ރަބީޢުލް އައްވަލް",
  "ރަބީޢުލް އާޚިރު",
  "ޖުމާދަލް އޫލާ",
  "ޖުމާދަލް އާޚިރާ",
  "ރަޖަބު",
  "ޝަޢުބާން",
  "ރަމަޟާން",
  "ޝައްވާލު",
  "ޛުލްޤަޢިދާ",
  "ޛުލްޙިއްޖާ",
] as const

const dhivehiWeekdays = ["އާދީއްތަ", "ހޯމަ", "އަންގާރަ", "ބުދަ", "ބުރާސްފަތި", "ހުކުރު", "ހޮނިހިރު"] as const

const dhivehiWeekdayShort = ["އާ", "ހޯ", "އަން", "ބު", "ބުރާ", "ހު", "ހޮ"] as const

function getHijriDateParts(date: Date) {
  const monthIndex = Number(hijriDateLib.format(date, "M")) - 1
  return {
    day: hijriDateLib.format(date, "d"),
    month: hijriMonths[monthIndex] ?? "",
    year: hijriDateLib.format(date, "yyyy"),
  }
}

function formatHijriDate(date: Date) {
  const { day, month, year } = getHijriDateParts(date)
  return `${day} ${month} ${year}`
}

function formatHijriMonthYear(date: Date) {
  const { month, year } = getHijriDateParts(date)
  return `${month} ${year}`
}

function DvHijriCalendar({
  className,
  classNames,
  showOutsideDays = true,
  captionLayout = "label",
  buttonVariant = "ghost",
  formatters,
  labels,
  components,
  dir = "rtl",
  lang = "dv",
  ...props
}: React.ComponentProps<typeof DayPicker> & {
  buttonVariant?: React.ComponentProps<typeof Button>["variant"]
}) {
  const defaultClassNames = getDefaultClassNames()

  return (
    <DayPicker
      showOutsideDays={showOutsideDays}
      className={cn(
        "group/calendar bg-background p-3 [--cell-size:--spacing(8)] [[data-slot=card-content]_&]:bg-transparent [[data-slot=popover-content]_&]:bg-transparent",
        String.raw`rtl:**:[.rdp-button\_next>svg]:rotate-180`,
        String.raw`rtl:**:[.rdp-button\_previous>svg]:rotate-180`,
        className
      )}
      captionLayout={captionLayout}
      locale={enUS}
      numerals="latn"
      dir={dir}
      lang={lang}
      formatters={{
        formatCaption: formatHijriMonthYear,
        formatMonthDropdown: (date) => getHijriDateParts(date).month,
        formatYearDropdown: (date) => getHijriDateParts(date).year,
        formatWeekdayName: (date) => dhivehiWeekdayShort[date.getDay()],
        ...formatters,
      }}
      labels={{
        labelNav: () => "ކަލަންޑަރުގެ މަސްތައް",
        labelGrid: (date) => formatHijriMonthYear(date),
        labelMonthDropdown: () => "މަސް ހޮވާ",
        labelYearDropdown: () => "އަހަރު ހޮވާ",
        labelNext: () => "ދެން އޮތް މަސް",
        labelPrevious: () => "ކުރީގެ މަސް",
        labelDayButton: (date) => formatHijriDate(date),
        labelWeekday: (date) => dhivehiWeekdays[date.getDay()],
        ...labels,
      }}
      classNames={{
        root: cn("w-fit", defaultClassNames.root),
        months: cn("relative flex flex-col gap-4 md:flex-row", defaultClassNames.months),
        month: cn("flex w-full flex-col gap-4", defaultClassNames.month),
        nav: cn(
          "absolute inset-x-0 top-0 flex w-full items-center justify-between gap-1",
          defaultClassNames.nav
        ),
        button_previous: cn(
          buttonVariants({ variant: buttonVariant }),
          "size-(--cell-size) p-0 select-none aria-disabled:opacity-50",
          defaultClassNames.button_previous
        ),
        button_next: cn(
          buttonVariants({ variant: buttonVariant }),
          "size-(--cell-size) p-0 select-none aria-disabled:opacity-50",
          defaultClassNames.button_next
        ),
        month_caption: cn(
          "flex h-(--cell-size) w-full items-center justify-center px-(--cell-size)",
          defaultClassNames.month_caption
        ),
        dropdowns: cn(
          "flex h-(--cell-size) w-full items-center justify-center gap-1.5 text-sm font-medium",
          defaultClassNames.dropdowns
        ),
        dropdown_root: cn(
          "relative rounded-md border border-input shadow-xs has-focus:border-ring has-focus:ring-[3px] has-focus:ring-ring/50",
          defaultClassNames.dropdown_root
        ),
        dropdown: cn("absolute inset-0 bg-popover opacity-0", defaultClassNames.dropdown),
        caption_label: cn(
          "font-medium select-none",
          captionLayout === "label"
            ? "text-sm"
            : "flex h-8 items-center gap-1 rounded-md pe-1 ps-2 text-sm [&>svg]:size-3.5 [&>svg]:text-muted-foreground",
          defaultClassNames.caption_label
        ),
        month_grid: cn("w-full border-collapse", defaultClassNames.month_grid),
        weekdays: cn("flex", defaultClassNames.weekdays),
        weekday: cn(
          "flex-1 rounded-md px-1 text-[0.8rem] font-normal whitespace-nowrap text-muted-foreground select-none",
          defaultClassNames.weekday
        ),
        week: cn("mt-2 flex w-full", defaultClassNames.week),
        week_number_header: cn("w-(--cell-size) select-none", defaultClassNames.week_number_header),
        week_number: cn(
          "text-[0.8rem] text-muted-foreground select-none",
          defaultClassNames.week_number
        ),
        day: cn(
          "group/day relative aspect-square h-full w-full p-0 text-center select-none [&:last-child[data-selected=true]_button]:rounded-e-md",
          props.showWeekNumber
            ? "[&:nth-child(2)[data-selected=true]_button]:rounded-s-md"
            : "[&:first-child[data-selected=true]_button]:rounded-s-md",
          defaultClassNames.day
        ),
        range_start: cn("rounded-s-md bg-accent", defaultClassNames.range_start),
        range_middle: cn("rounded-none", defaultClassNames.range_middle),
        range_end: cn("rounded-e-md bg-accent", defaultClassNames.range_end),
        today: cn(
          "rounded-md bg-accent text-accent-foreground data-[selected=true]:rounded-none",
          defaultClassNames.today
        ),
        outside: cn(
          "text-muted-foreground aria-selected:text-muted-foreground",
          defaultClassNames.outside
        ),
        disabled: cn("text-muted-foreground opacity-50", defaultClassNames.disabled),
        hidden: cn("invisible", defaultClassNames.hidden),
        ...classNames,
      }}
      components={{
        Root: ({ className, rootRef, ...props }) => (
          <div data-slot="dv-hijri-calendar" ref={rootRef} className={cn(className)} {...props} />
        ),
        Chevron: ({ className, orientation, ...props }) => {
          if (orientation === "left") {
            return <ChevronLeftIcon className={cn("size-4", className)} {...props} />
          }
          if (orientation === "right") {
            return <ChevronRightIcon className={cn("size-4", className)} {...props} />
          }
          return <ChevronDownIcon className={cn("size-4", className)} {...props} />
        },
        DayButton: DvHijriCalendarDayButton,
        WeekNumber: ({ children, ...props }) => (
          <td {...props}>
            <div className="flex size-(--cell-size) items-center justify-center text-center">
              {children}
            </div>
          </td>
        ),
        ...components,
      }}
      {...props}
    />
  )
}

function DvHijriCalendarDayButton({
  className,
  day,
  modifiers,
  ...props
}: React.ComponentProps<typeof DayButton>) {
  const defaultClassNames = getDefaultClassNames()
  const ref = React.useRef<HTMLButtonElement>(null)

  React.useEffect(() => {
    if (modifiers.focused) ref.current?.focus()
  }, [modifiers.focused])

  return (
    <Button
      ref={ref}
      variant="ghost"
      size="icon"
      data-day={formatHijriDate(day.date)}
      data-selected-single={
        modifiers.selected &&
        !modifiers.range_start &&
        !modifiers.range_end &&
        !modifiers.range_middle
      }
      data-range-start={modifiers.range_start}
      data-range-end={modifiers.range_end}
      data-range-middle={modifiers.range_middle}
      className={cn(
        "flex aspect-square size-auto w-full min-w-(--cell-size) flex-col gap-1 leading-none font-normal group-data-[focused=true]/day:relative group-data-[focused=true]/day:z-10 group-data-[focused=true]/day:border-ring group-data-[focused=true]/day:ring-[3px] group-data-[focused=true]/day:ring-ring/50 data-[range-end=true]:rounded-md data-[range-end=true]:rounded-e-md data-[range-end=true]:bg-primary data-[range-end=true]:text-primary-foreground data-[range-middle=true]:rounded-none data-[range-middle=true]:bg-accent data-[range-middle=true]:text-accent-foreground data-[range-start=true]:rounded-md data-[range-start=true]:rounded-s-md data-[range-start=true]:bg-primary data-[range-start=true]:text-primary-foreground data-[selected-single=true]:bg-primary data-[selected-single=true]:text-primary-foreground dark:hover:text-accent-foreground [&>span]:text-xs [&>span]:opacity-70",
        defaultClassNames.day,
        className
      )}
      {...props}
    />
  )
}

export {
  DvHijriCalendar,
  DvHijriCalendarDayButton,
  formatHijriDate,
  formatHijriMonthYear,
  getHijriDateParts,
  hijriMonths,
}
